const targetName = $("Compute Base Filename").first().json.baseFilename;
const checksum = $("Hash File Content").first().json.checksum;
const items = $input.all();
const collision = items.some(function(i) { return i.json && i.json.name === targetName; });
let finalName = targetName;
if (collision) {
  const dotIndex = targetName.lastIndexOf(".");
  const base = dotIndex > -1 ? targetName.slice(0, dotIndex) : targetName;
  const ext = dotIndex > -1 ? targetName.slice(dotIndex) : "";
  finalName = base + "_" + checksum.slice(0, 8) + ext;
}
return [{ json: Object.assign({}, $("Compute Base Filename").first().json, { new_filename: finalName }) }];
